"""Approved six-month ERA Community Missions authored pack.

The payload is compressed only to keep this source file reviewable. It is the
same authored JSON derived from the approved master ToR; nothing is generated
by AI at runtime.
"""

from __future__ import annotations

import base64
import json
import zlib

_PACK = ""


def load_community_missions() -> list[dict]:
    raw = zlib.decompress(base64.b64decode(_PACK))
    payload = json.loads(raw.decode("utf-8"))
    items = payload.get("items", [])
    if len(items) != 26:
        raise RuntimeError(f"community missions pack must contain 26 items, got {len(items)}")
    return items
